const MEAT_REGIONS = {"emilia": {"jp": "エミリア・ロマーニャ", "en": "EMILIA-ROMAGNA", "label": [10.6, 44.7], "short": "エミリア", "desc": "パルマ、ボローニャ、ピアチェンツァのある美食の地方。プロシュット・ディ・パルマ、モルタデッラ、クラテッロなど、イタリアの加工肉の宝庫。", "pick": "イタリア"}, "friuli": {"jp": "フリウリ", "en": "FRIULI", "label": [13.0, 46.15], "desc": "アルプスとアドリア海にはさまれた北東部。サン・ダニエーレの丘で、海と山の風を受けて生ハムが熟成する。", "pick": "イタリア"}, "altoadige": {"jp": "アルト・アディジェ", "en": "ALTO ADIGE", "label": [11.35, 46.6], "short": "アルト・アディジェ", "desc": "オーストリアと接する南チロル。生ハムを軽く燻製した「スペック」の産地で、ドイツ語圏の文化が残る。", "pick": "イタリア"}, "lombardia": {"jp": "ロンバルディア", "en": "LOMBARDIA", "label": [9.6, 45.9], "desc": "北部の州。アルプスのヴァルテッリーナ渓谷では、牛のもも肉を乾燥させたブレザオラが造られる。ミラノ風のサラミも。", "pick": "イタリア"}, "toscana": {"jp": "トスカーナ", "en": "TOSCANA", "label": [11.2, 43.4], "desc": "フィレンツェのある州。フェンネルの種入りのサラミ「フィノッキオーナ」や、大理石の産地コロンナータの背脂の塩漬け「ラルド」が名物。", "pick": "イタリア"}, "umbria": {"jp": "ウンブリア（ノルチャ）", "en": "UMBRIA", "label": [13.1, 42.8], "short": "ノルチャ", "desc": "イタリア中部の山あいの町ノルチャは、豚肉加工職人「ノルチーノ」の語源となったほどの加工肉の里。", "pick": "イタリア"}, "calabria": {"jp": "カラブリア", "en": "CALABRIA", "label": [16.3, 38.9], "desc": "イタリア半島の先端。唐辛子をたっぷり使った、パンに塗れるやわらかいサラミ「ンドゥイヤ」の故郷。", "pick": "イタリア"}, "andalucia": {"jp": "アンダルシア（ハブーゴ）", "en": "ANDALUCÍA", "label": [-6.6, 37.9], "short": "ハブーゴ", "desc": "南西部ウエルバ県のハブーゴ村は、イベリコ豚の生ハムの聖地。山あいの乾いた風が、生ハムをゆっくりと熟成させる。", "pick": "スペイン"}, "extremadura": {"jp": "エストレマドゥーラ", "en": "EXTREMADURA", "label": [-6.2, 39.2], "desc": "ポルトガルと接する地方。どんぐりの森（デエサ）が広がり、イベリコ豚が放牧される。", "pick": "スペイン"}, "salamanca": {"jp": "サラマンカ（ギフエロ）", "en": "GUIJUELO", "label": [-5.7, 40.55], "short": "ギフエロ", "desc": "カスティーリャ・イ・レオン州の高原の町ギフエロ。寒く乾いた気候で、甘みのあるイベリコの生ハムが造られる。", "pick": "スペイン"}, "teruel": {"jp": "アラゴン（テルエル）", "en": "TERUEL", "label": [-1.1, 40.35], "short": "テルエル", "desc": "スペイン東部の高原。白豚の生ハム「ハモン・デ・テルエル」はスペインで最初に原産地呼称を得た生ハム。", "pick": "スペイン"}, "leon": {"jp": "レオン・ナバラ", "en": "LEÓN & NAVARRA", "label": [-4.0, 42.6], "short": "レオン", "desc": "北部の地方。牛肉の乾燥肉セシナや、パンプローナ風のチョリソなど。", "pick": "スペイン"}, "catalunya": {"jp": "カタルーニャ", "en": "CATALUNYA", "label": [1.9, 41.8], "desc": "バルセロナのある地方。細長いドライソーセージ「フエ」や、生のソーセージ「ブティファラ」の故郷。", "pick": "スペイン"}, "bayern": {"jp": "バイエルン", "en": "BAYERN", "label": [11.5, 48.6], "desc": "ミュンヘンを州都とする南部の州。白いソーセージのヴァイスヴルストや、小さなニュルンベルガーなど、名物ソーセージがそろう。", "pick": "ドイツ"}, "thueringen": {"jp": "テューリンゲン", "en": "THÜRINGEN", "label": [11.0, 50.9], "desc": "ドイツ中部の森の州。マジョラムのきいた「テューリンガー・ローストブラートヴルスト」は、500年以上の歴史を持つといわれる。", "pick": "ドイツ"}, "hessen": {"jp": "ヘッセン（フランクフルト）", "en": "HESSEN", "label": [8.7, 50.2], "short": "フランクフルト", "desc": "フランクフルトの名を持つ細長いゆでソーセージ「フランクフルター・ヴュルストヒェン」の故郷。", "pick": "ドイツ"}, "westfalen": {"jp": "ヴェストファーレン", "en": "WESTFALEN", "label": [7.8, 51.9], "desc": "北西部の地方。ブナの木でいぶして熟成させる生ハム「ヴェストフェーリッシャー・シンケン」で知られる。", "pick": "ドイツ"}, "schwarzwald": {"jp": "シュヴァルツヴァルト", "en": "SCHWARZWALD", "label": [8.2, 48.1], "short": "黒い森", "desc": "南西部の「黒い森」。もみの木でいぶした生ハム「シュヴァルツヴェルダー・シンケン」が名物。", "pick": "ドイツ"}, "berlin": {"jp": "ベルリン", "en": "BERLIN", "label": [13.4, 52.5], "desc": "首都ベルリン。焼いたソーセージにカレー粉とケチャップをかける「カリーヴルスト」の発祥の地。", "pick": "ドイツ"}, "paysbasque": {"jp": "バスク（バイヨンヌ）", "en": "BAYONNE", "label": [-1.3, 43.4], "short": "バイヨンヌ", "desc": "スペイン国境に近いバイヨンヌ。ピレネー山麓のアドゥール川流域で、塩と風で熟成させる生ハムの産地。", "pick": "フランス"}, "lyon": {"jp": "リヨン", "en": "LYON", "label": [4.8, 45.8], "desc": "「美食の都」リヨン。サラミの「ロゼット・ド・リヨン」や、ゆでて食べる大きなソーセージ「ソシソン・ド・リヨン」が名物。", "pick": "フランス"}, "paris": {"jp": "パリ", "en": "PARIS", "label": [2.35, 48.85], "desc": "パリでは、しっとりとした加熱ハム「ジャンボン・ド・パリ」がバゲットのサンドイッチの定番。", "pick": "フランス"}, "sarthe": {"jp": "ロワール（ル・マン）", "en": "LE MANS", "label": [0.2, 48.0], "short": "ル・マン", "desc": "ロワール地方のル・マンやトゥールは、豚肉を脂でじっくり煮てほぐしたリエットの本場。", "pick": "フランス"}, "portugal": {"jp": "ポルトガル", "en": "PORTUGAL", "desc": "黒豚の生ハム「プレズント」や、燻製したチョリソ「ショリソ」、鶏肉やパンを詰めたソーセージ「アリェイラ」など、素朴で力強い加工肉の国。", "pick": "ポルトガル"}, "uk": {"jp": "イギリス", "en": "UNITED KINGDOM", "desc": "朝食に欠かせないベーコンとソーセージ、そして黒いブラッドソーセージ「ブラックプディング」の国。渦巻き状のカンバーランド・ソーセージも名物。", "pick": "イギリス"}, "austria": {"jp": "オーストリア", "en": "AUSTRIA", "desc": "ウインナー（ウィーン風）ソーセージの故郷。チーズ入りのケーゼクライナーなど、屋台のソーセージ文化が根づいている。", "pick": "オーストリア"}, "hungary": {"jp": "ハンガリー", "en": "HUNGARY", "desc": "パプリカの国。冬の冷たい空気で熟成させる「冬のサラミ（テーリサラーミ）」や、パプリカで赤く色づいたソーセージ「コルバース」が名物。", "pick": "ハンガリー"}, "poland": {"jp": "ポーランド", "en": "POLAND", "desc": "ソーセージを「キェウバサ」と総称する、ドイツと並ぶソーセージの国。燻製の香りが豊か。", "pick": "ポーランド"}, "usa": {"jp": "アメリカ", "en": "USA", "desc": "カリカリに焼くベーコン、ホットドッグのフランクフルト、ニューヨークのパストラミ、ピザのペパロニなど、日常の味として加工肉が大活躍する国。", "pick": "アメリカ"}, "china": {"jp": "中国", "en": "CHINA", "desc": "浙江省の金華ハムは、中国料理のスープの旨みの素として欠かせない。甘い腸詰め「臘腸（ラーチャン）」も広く食べられる。", "pick": "中国"}, "japan": {"jp": "日本", "en": "JAPAN", "desc": "明治時代に西洋の製法が伝わり、ロースハムやウインナーなど、日本独自の食べやすい加工肉が発展した。皮なしの細いウインナーや、皮がパリッとしたあらびきウインナーが食卓の定番。", "pick": "日本"}};
const MEAT_COUNTRIES = {"italy": {"jp": "イタリア", "style": "イタリア", "en": "ITALY", "mark": [12.5, 42.5], "map": "italy", "regions": ["friuli", "altoadige", "lombardia", "emilia", "toscana", "umbria", "calabria"], "desc": "生ハム（プロシュット）とサラミ（サルーミ）の国。北部の生ハム、中部のサラミ、南部の唐辛子の効いた加工肉と、地方ごとに個性が分かれる。地図の産地をタップすると、その土地の加工肉が表示される。"}, "spain": {"jp": "スペイン", "style": "スペイン", "en": "SPAIN", "mark": [-3.7, 40.2], "map": "spain", "regions": ["andalucia", "extremadura", "salamanca", "teruel", "leon", "catalunya"], "desc": "ハモン（生ハム）とチョリソの国。どんぐりを食べて育つイベリコ豚の生ハムは、世界最高峰の生ハムとされる。"}, "germany": {"jp": "ドイツ", "style": "ドイツ", "en": "GERMANY", "mark": [10.3, 51.0], "map": "meat_germany", "regions": ["westfalen", "berlin", "hessen", "thueringen", "schwarzwald", "bayern"], "desc": "1,500種類を超えるといわれるソーセージの国。生で焼く「ブラートヴルスト」、ゆでる「ブリューヴルスト」、レバーや血を使う「コッホヴルスト」、熟成させる「ローヴルスト」の大きく4つに分かれ、町ごとに名物がある。"}, "france": {"jp": "フランス", "style": "フランス", "en": "FRANCE", "mark": [2.4, 46.6], "map": "france", "regions": ["paysbasque", "sarthe", "paris", "lyon"], "desc": "シャルキュトリー（加工肉）の伝統を持つ国。生ハム、サラミ（ソシソン・セック）、パテやリエットなど、肉屋の店先の品ぞろえが豊か。"}, "portugal": {"jp": "ポルトガル", "style": "ポルトガル", "en": "PORTUGAL", "mark": [-8.0, 39.6], "regions": ["portugal"]}, "uk": {"jp": "イギリス", "style": "イギリス", "en": "UNITED KINGDOM", "mark": [-1.5, 52.5], "regions": ["uk"]}, "austria": {"jp": "オーストリア", "style": "オーストリア", "en": "AUSTRIA", "mark": [14.5, 47.5], "regions": ["austria"]}, "hungary": {"jp": "ハンガリー", "style": "ハンガリー", "en": "HUNGARY", "mark": [19.3, 47.1], "regions": ["hungary"]}, "poland": {"jp": "ポーランド", "style": "ポーランド", "en": "POLAND", "mark": [19.4, 52.1], "regions": ["poland"]}, "usa": {"jp": "アメリカ", "style": "アメリカ", "en": "USA", "regions": ["usa"], "minor": true}, "china": {"jp": "中国", "style": "中国", "en": "CHINA", "regions": ["china"], "minor": true}, "japan": {"jp": "日本", "style": "日本", "en": "JAPAN", "regions": ["japan"], "minor": true}};
