const MEAT_TYPES = [{"id": "rawham", "name": "生ハム", "en": "Dry-cured Ham", "kind": "ハム・ベーコン", "home": "イタリア、スペイン、フランス、ドイツ", "p": [4, 5, 4, 1, 0, 0, 4, 2], "tags": ["熟成", "旨み", "脂の甘み"], "desc": "豚のもも肉を塩漬けにして、加熱せずに長い時間をかけて乾燥・熟成させたハム。熟成のあいだにたんぱく質が分解され、旨みと甘い香りが生まれる。燻製するもの（ドイツなど）としないもの（イタリア・スペインなど）がある。"}, {"id": "cookedham", "name": "加熱ハム", "en": "Cooked Ham", "kind": "ハム・ベーコン", "home": "フランス、日本、ドイツ", "p": [3, 3, 2, 2, 0, 0, 0, 1], "tags": ["しっとり", "やさしい塩気"], "desc": "塩漬けにした肉を、ゆでたり蒸したりして加熱したハム。しっとりやわらかく、やさしい味わい。日本のロースハムやボンレスハムもこの仲間。"}, {"id": "bacon", "name": "ベーコン", "en": "Bacon", "kind": "ハム・ベーコン", "home": "イギリス、アメリカ、イタリア、日本", "p": [4, 4, 5, 4, 1, 0, 1, 2], "tags": ["燻製", "脂の甘み", "焼いて"], "desc": "豚のばら肉などを塩漬けにして燻製したもの。イタリアのパンチェッタは燻製しない塩漬けばら肉。焼くと脂が溶けて香ばしく、料理の旨みの素にもなる。"}, {"id": "dryaged", "name": "乾燥・熟成肉", "en": "Air-dried Meat", "kind": "ハム・ベーコン", "home": "イタリア、スペイン、アメリカ", "p": [4, 4, 1, 1, 1, 1, 3, 4], "tags": ["赤身", "かみごたえ"], "desc": "牛肉などの赤身を塩漬けにして乾燥させたもの。脂が少なく、しっかりとした旨み。イタリアのブレザオラ、スペインのセシナ、ビーフジャーキーなど。"}, {"id": "salami", "name": "サラミ・ドライソーセージ", "en": "Dry Sausage", "kind": "ソーセージ", "home": "イタリア、スペイン、ハンガリー、フランス", "p": [4, 4, 4, 1, 3, 1, 4, 4], "tags": ["熟成", "スパイス", "脂の粒"], "desc": "ひき肉と脂、塩、香辛料を腸に詰め、加熱せずに発酵・乾燥させたソーセージ。乳酸菌の働きでほのかな酸味と旨みが生まれる。薄く切ってそのまま食べる。"}, {"id": "bratwurst", "name": "焼くソーセージ（ブラートヴルスト）", "en": "Bratwurst", "kind": "ソーセージ", "home": "ドイツ、オーストリア、イギリス", "p": [3, 4, 4, 1, 2, 3, 0, 2], "tags": ["ジューシー", "ハーブ", "焼いて"], "desc": "生のひき肉を詰めたソーセージで、焼いて食べるもの。ドイツ語の「ブラート」は「焼く」。マジョラムなどのハーブがきいたジューシーな味わい。"}, {"id": "brueh", "name": "ゆでソーセージ（ブリューヴルスト）", "en": "Brühwurst", "kind": "ソーセージ", "home": "ドイツ、オーストリア、日本", "p": [3, 3, 3, 2, 1, 1, 0, 1], "tags": ["ぷりっと", "パリッ", "ゆでて"], "desc": "細かく練った肉を腸に詰め、ゆでたり燻製したりして火を通したソーセージ。フランクフルトやウインナー、ボローニャのモルタデッラもこの仲間。ぷりっとした食感で、温め直して食べる。"}, {"id": "kochwurst", "name": "レバー・血のソーセージ", "en": "Kochwurst", "kind": "ソーセージ", "home": "ドイツ、イギリス、フランス、スペイン", "p": [3, 4, 4, 1, 2, 2, 1, 1], "tags": ["濃厚", "レバー", "パンに塗る"], "desc": "火を通したレバーや血、脂などを詰めて加熱したソーセージ。パンに塗るレバーヴルストや、黒いブラッドソーセージなど、濃厚でクセのある味わい。"}, {"id": "fat", "name": "脂の塩漬け・パテ", "en": "Lardo & Pâté", "kind": "そのほか", "home": "イタリア、フランス", "p": [3, 3, 5, 0, 1, 3, 2, 0], "tags": ["とろける", "ハーブ", "パンにのせて"], "desc": "豚の背脂を塩とハーブで熟成させたラルドや、肉を脂で煮てほぐしたリエット、パテなど。パンにのせて、口の中でとろける脂の甘さを楽しむ。"}];
